def slug(n): return re.sub(r'-+','-',re.sub(r'[^a-z0-9]+','-',n.lower().replace("’","").replace("'",""))).strip('-')
BASE=dict(business='',category_as_listed='',phone='',email='',email_source='',linkedin_url='',linkedin_source='',contact_person='',role='',contact_source='',website='',address='',city='',state='',market='',lead_origin='',rating='',reviews='',source_url='',tel_numbers=[],tel_source='',socials=[],building='',suite='',trade_memberships=[],hooks=[],is_diamond_trade=True,scope_reason='',drop_reason='')
MK={'PA':('Philadelphia','PA','Philadelphia, PA'),'MA':('Boston','MA','Boston, MA'),'NY':('New York','NY','New York, NY')}
written=[]
def rec(st,ypname=None,**kw):
    d=dict(BASE); d['tel_numbers']=[];d['socials']=[];d['trade_memberships']=[];d['hooks']=[]
    c,s,m=MK[st]; d.update(city=c,state=s,market=m)
    if ypname:
        y=yp[ypname]
        d.update(business=ypname,category_as_listed=y['cats'].replace(',',', '),phone=y['phone'],address=y['addr']+', '+y['loc'],lead_origin='YellowPages',source_url=y['mip'])
        mm=re.search(r'(Ste|Suite|#|Fl)\s*(\w+)',y['addr'])
        if mm: d['suite']=mm.group(0)
    d.update(kw)
    if not d['is_diamond_trade'] and not d['drop_reason']: raise Exception(d['business'])
    sl=kw.pop('slug',None) or slug(d['business']); d.pop('slug',None)
    json.dump(d,open(OUT+sl+'.json','w'),indent=2,ensure_ascii=False); written.append(sl)
